/**
 * Writes one `.env` file per deployable unit.
 *
 * The repository root holds the shared values (`.env.local`). Each unit needs
 * its own copy, with its own address and its own database URL.
 *
 *   npm run env:sync
 *   npm run env:sync -- --neon   point the backend at the hosted database
 *
 * The generated files are git-ignored. Run this again after changing the
 * database URLs.
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");

/** The Backend API's port. */
const API_PORT = 4000;

/** The web client's port. */
const WEB_PORT = 5173;

/**
 * One database, shared by the whole backend.
 *
 * The pool parameters matter. The hosted database allows only a handful of
 * concurrent connections per branch, so the client pool is kept at one, and
 * the connect timeout has to allow for the compute waking up.
 */
const LOCAL_DATABASE_URL =
  "postgresql://postgres:postgres@127.0.0.1:5432/postgres?pgbouncer=true&connection_limit=1&connect_timeout=15&pool_timeout=15";
const LOCAL_DIRECT_DATABASE_URL =
  "postgresql://postgres:postgres@127.0.0.1:5432/postgres";

/** Reads a KEY=value map out of a dotenv file. */
function readEnvFile(path) {
  if (!existsSync(path)) return {};
  const values = {};
  for (const line of readFileSync(path, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const index = trimmed.indexOf("=");
    if (index === -1) continue;
    values[trimmed.slice(0, index).trim()] = trimmed
      .slice(index + 1)
      .trim()
      .replace(/^["']|["']$/g, "");
  }
  return values;
}

const rootEnv = {
  ...readEnvFile(join(root, ".env")),
  ...readEnvFile(join(root, ".env.local")),
  // Environment variables win, so this script also works on a build host
  // where the values are injected rather than written to a file.
  ...process.env,
};

const useNeon = process.argv.includes("--neon");

const jwtSecret =
  rootEnv.JWT_SECRET ??
  "glucoplate-development-only-secret-change-me-please";

const corsOrigins =
  rootEnv.CORS_ORIGINS ??
  `http://localhost:${WEB_PORT},http://localhost:8081,*`;

/**
 * Adds the pool parameters Prisma and the host pooler need.
 *
 * `pgbouncer=true`     only for a POOLED endpoint (the hostname contains
 *                       "-pooler"): the pooler is in transaction mode, so
 *                       Prisma must not use prepared statements
 * `connection_limit=1` Prisma's own pool size, kept small so the backend
 *                       stays well inside the host's connection limit
 * `connect_timeout=15` the host scales to zero, and waking the compute takes
 *                       seconds
 * `pool_timeout=15`    do not fail fast while the pool is busy
 */
function withPoolParams(url) {
  if (!url) return url;

  const [base, query = ""] = url.split("?");
  const params = new URLSearchParams(query);

  if (base.includes("-pooler") && !params.has("pgbouncer")) {
    params.set("pgbouncer", "true");
  }
  if (!params.has("connection_limit")) params.set("connection_limit", "1");
  if (!params.has("connect_timeout")) params.set("connect_timeout", "15");
  if (!params.has("pool_timeout")) params.set("pool_timeout", "15");

  return `${base}?${params.toString()}`;
}

let written = 0;

function writeUnit(relativePath, lines) {
  const file = join(root, relativePath);
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, `${lines.join("\n").trimEnd()}\n`, "utf8");
  written += 1;
  console.log(`  wrote ${relativePath}`);
}

// --- The Backend API ------------------------------------------------------
const backendDir = join(root, "apps", "backend");
if (existsSync(backendDir)) {
  const databaseUrl = useNeon
    ? withPoolParams(rootEnv.DATABASE_URL ?? LOCAL_DATABASE_URL)
    : withPoolParams(LOCAL_DATABASE_URL);
  const directUrl = useNeon
    ? (rootEnv.DIRECT_DATABASE_URL ?? databaseUrl)
    : LOCAL_DIRECT_DATABASE_URL;

  writeUnit("apps/backend/.env", [
    "# Generated by `npm run env:sync`. Git-ignored.",
    `PORT=${API_PORT}`,
    "SERVICE_NAME=glucoplate-api",
    `DATABASE_URL=${databaseUrl}`,
    `DIRECT_DATABASE_URL=${directUrl}`,
    `JWT_SECRET=${jwtSecret}`,
    `CORS_ORIGINS=${corsOrigins}`,
    "LOG_LEVEL=info",
  ]);
}

// --- The web client --------------------------------------------------------
const webDir = join(root, "apps", "web");
if (existsSync(webDir)) {
  writeUnit("apps/web/.env.local", [
    "# Generated by `npm run env:sync`. Git-ignored.",
    `VITE_API_URL=http://127.0.0.1:${API_PORT}`,
    "VITE_DEBUG_API=false",
  ]);
}

// --- The mobile client -----------------------------------------------------
const mobileDir = join(root, "apps", "mobile");
if (existsSync(mobileDir)) {
  writeUnit("apps/mobile/.env", [
    "# Generated by `npm run env:sync`. Git-ignored.",
    `EXPO_PUBLIC_API_URL=http://127.0.0.1:${API_PORT}`,
    "EXPO_PUBLIC_DEBUG=false",
  ]);
}

console.log(`env:sync — wrote ${written} file(s).`);
